// sévérité n'en contient aucune.
var structuralKeys = map[string]bool{
	"esc": true, "enter": true, "tab": true, "shift+tab": true,
	"up": true, "down": true, "left": true, "right": true,
	"pgup": true, "pgdown": true, "home": true, "end": true,
	" ": true, "/": true, "?": true,
