// a link needs asking. That is what keeps the cycle guard free on the common
// path — one EvalSymlinks per link crossed, none per directory.
func walkSubRepos(dir, real string, showHidden bool, seen map[string]bool, found *subRepoScan) {
	if seen[real] {
		return
	}
	seen[real] = true

	if isRepo(dir) {
		found.Repos = append(found.Repos, dir)
