//
// The three entries are asked for in this order because HEAD is the one almost
// nothing else is called: a directory that has no HEAD costs one stat, which is
// every directory the walk crosses.
func isBareRepo(dir string) bool {
	for _, name := range []string{"HEAD", "objects", "refs"} {
		if _, err := os.Stat(filepath.Join(dir, name)); err != nil {
			return false
		}
	}
	return true
}
