// needs SeCreateSymbolicLinkPrivilege on Windows, which a plain user session
// does not have unless Developer Mode is on. The defect this covers was found
// on Windows with a junction, so skipping here is a real gap — CI runs on Linux
// and does exercise it.
func linkDir(t *testing.T, target, link string) {
	t.Helper()
	if err := os.Symlink(target, link); err != nil {
		t.Skipf("cannot create a directory link here: %v", err)
	}
}

