//     link's own path, so the chain costs nothing to reconstruct — the walk
//     climbs to the filesystem root rather than to the base, because a link
//     above the base drags the base back in with it.
//   - **Already entered through another link.** The same repositories under a
//     second name, which is a second scan of each rather than a loop.
func mayFollow(link string, crossed *[]os.FileInfo) (bool, error) {
	target, err := os.Stat(link)
	if err != nil {
